 const save=()=>{if(!editing?.title.trim())return;const normalized={...editing,tabs:editing.tabs?.length?editing.tabs:[editing.status||'Backlog']};setItems(old=>old.some(x=>x.id===editing.id)?old.map(x=>x.id===editing.id?normalized:x):[normalized,...old]);setEditing(null)}
