const readAttachment=async(id:string)=>{const db=await attachmentDB();return new Promise<Blob|null>((resolve,reject)=>{const store=db.transaction('files').objectStore('files'),req=store.get(attachmentKey(id));req.onsuccess=()=>{const value=req.result;if(value){resolve(value?.blob||value);db.close();return}const legacy=store.get(id);legacy.onsuccess=()=>{const old=legacy.result;resolve(old?.blob||old||null);db.close()};legacy.onerror=()=>{reject(legacy.error);db.close()}};req.onerror=()=>{reject(req.error);db.close()}})}
const deleteAttachment=async(id:string)=>{const db=await attachmentDB();await new Promise<void>((resolve,reject)=>{const tx=db.transaction('files','readwrite'),store=tx.objectStore('files');store.delete(attachmentKey(id));store.delete(id);tx.oncomplete=()=>{resolve();db.close()};tx.onerror=()=>{reject(tx.error);db.close()}})}
