function WhatsAppChatPreview({chats,selectedChatId}:{chats:ImportedConversation[];selectedChatId?:string}){const [active,setActive]=useState(chats[0]?.id||'');const [all,setAll]=useState(false);useEffect(()=>{if(selectedChatId&&chats.some(x=>x.id===selectedChatId))setActive(selectedChatId)},[selectedChatId,chats]);useEffect(()=>{if(!chats.some(x=>x.id===active))setActive(chats[0]?.id||'')},[chats,active]);const chat=chats.find(x=>x.id===active),visible=chat?(all?chat.messages:chat.messages.slice(-55)):[];let prev='';return <section className="whatsapp-preview-view"><div className="eyebrow"><MessageCircle size={14}/> CHAT EXPORT <span className="dm-preview-tag">IMPORTED</span></div><div className="dm-page-heading"><div><h1>{chat?.name||'WhatsApp chats'}</h1><p>{chat?'WhatsApp conversation':'Import chat folders from Settings.'}</p></div><span className="dm-thread-count">{chats.length} conversations</span></div>{!chat?<div className="dm-empty-state"><MessageCircle size={24}/><strong>No WhatsApp conversations imported</strong><span>Choose a WhatsApp Chat with [name] folder in Settings.</span></div>:<><div className="wa-chat-tabs">{chats.map(c=><button key={c.id} className={active===c.id?'active':''} onClick={()=>{setActive(c.id);setAll(false)}}>{c.name}</button>)}</div><div className="wa-chat-shell"><div className="wa-chat-topbar"><span className="wa-chat-avatar">{chat.name.slice(0,1)}</span><div><strong>{chat.name}</strong><small>WhatsApp conversation</small></div></div><div className="wa-chat-body">{visible.map(m=>{const changed=m.date!==prev;prev=m.date;return <div className="wa-record" key={m.id}>{changed&&<div className="wa-date-heading">{m.date}</div>}{m.kind==='system'?<div className="wa-system">{m.text}</div>:m.kind==='call'?<div className="wa-chat-row outgoing"><div className="wa-chat-bubble wa-call-record"><span><PhoneCall size={15}/> Outgoing call</span><time>{m.time}</time></div></div>:<div className={'wa-chat-row '+(m.sender==='you'?'outgoing':'incoming')}><div className="wa-chat-bubble"><div className="wa-chat-sender">{m.sender==='you'?'You':m.sender}</div><div className="wa-chat-text">{m.media?.length?<ImportedMedia items={m.media}/>:m.url?<a className="wa-link-preview" href={m.url} target="_blank" rel="noreferrer"><span className="wa-link-icon"><ExternalLink size={16}/></span><span><strong>{new URL(m.url).hostname.replace(/^www\./,'')}</strong><small>{m.url}</small></span></a>:<EmojiText text={m.text||''}/>}</div><time>{m.time}</time></div></div>}</div>})}</div>{!all&&chat.messages.length>55&&<button className="wa-show-all" onClick={()=>setAll(true)}>Show all {chat.messages.length} records</button>}</div></>}</section>}

function FollowRelationshipsView({data}:{data:FollowData|null}){const [filter,setFilter]=useState<'not-following-back'|'you-dont-follow'|'mutual'>('not-following-back'),[query,setQuery]=useState('');const following=data?.following||[],followers=data?.followers||[],followerSet=new Set(followers.map(x=>x.username.toLowerCase())),followingSet=new Set(following.map(x=>x.username.toLowerCase()));const rows=filter==='not-following-back'?following.filter(x=>!followerSet.has(x.username.toLowerCase())):filter==='you-dont-follow'?followers.filter(x=>!followingSet.has(x.username.toLowerCase())):following.filter(x=>followerSet.has(x.username.toLowerCase()));const shown=rows.filter(x=>x.username.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>a.username.localeCompare(b.username));return <section className="follow-relationships"><div className="eyebrow"><Users size={14}/> INSTAGRAM DATA <span className="dm-preview-tag">FOLLOW RELATIONSHIPS</span></div><div className="dm-page-heading"><div><h1>Follow relationships</h1><p>Compare your Instagram following and follower exports.</p></div></div>{!data?<div className="dm-empty-state"><Users size={24}/><strong>No follower data imported</strong><span>Import following.json and followers_1.json together in Settings → Import conversations.</span></div>:<><div className="follow-stats"><div><strong>{following.length}</strong><span>Following</span></div><div><strong>{followers.length}</strong><span>Followers</span></div><div><strong>{following.filter(x=>followerSet.has(x.username.toLowerCase())).length}</strong><span>Mutuals</span></div><div><strong>{following.filter(x=>!followerSet.has(x.username.toLowerCase())).length}</strong><span>Not following back</span></div></div><div className="follow-filter-tabs"><button className={filter==='not-following-back'?'active':''} onClick={()=>setFilter('not-following-back')}>Not following back <span>{following.filter(x=>!followerSet.has(x.username.toLowerCase())).length}</span></button><button className={filter==='you-dont-follow'?'active':''} onClick={()=>setFilter('you-dont-follow')}>You don't follow back <span>{followers.filter(x=>!followingSet.has(x.username.toLowerCase())).length}</span></button><button className={filter==='mutual'?'active':''} onClick={()=>setFilter('mutual')}>Mutuals <span>{following.filter(x=>followerSet.has(x.username.toLowerCase())).length}</span></button></div><input className="follow-search" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search usernames…"/><div className={'follow-account-list'+(filter==='mutual'?' mutual-grid':'')}>{shown.map(x=><a key={x.username} href={x.href} target="_blank" rel="noreferrer"><span className="follow-account-avatar">{x.username.slice(0,1).toUpperCase()}</span><strong>{x.username}</strong><ExternalLink size={13}/></a>)}{!shown.length&&<p className="muted">No accounts in this category match your search.</p>}</div><p className="fine-print left">Comparison is based on usernames in the two exports. It reflects the data at the time Instagram generated your archive.</p></>}</section>}
