 const refreshStorageUsage=async()=>{
  setStorageLoading(true);
  try{
   const localValue=(key:string)=>localStorage.getItem(key)||'';
   const localSize=(key:string)=>new Blob([localValue(key)]).size;
   let savedEntries:Entry[]=[];try{const parsed=JSON.parse(localValue('memento.entries')||'[]');if(Array.isArray(parsed))savedEntries=parsed}catch{}
   const nativeEntries=savedEntries.filter(entry=>!entry.importedBatch),importedEntries=savedEntries.filter(entry=>!!entry.importedBatch);
   const entriesBytes=new Blob([JSON.stringify(nativeEntries)]).size;
   const importedEntriesBytes=new Blob([JSON.stringify(importedEntries)]).size;
   let dmsBytes=0,mediaBytes=0;
   try{const chats=await loadChatData();dmsBytes=new Blob([JSON.stringify(chats)]).size}catch{}
   try{
    const db=await attachmentDB();
    mediaBytes=await new Promise<number>((resolve,reject)=>{const request=db.transaction('files').objectStore('files').getAll();request.onsuccess=()=>resolve((request.result||[]).reduce((sum:number,value:any)=>{const blob=value?.blob||value;return sum+(blob instanceof Blob?blob.size:new Blob([JSON.stringify(value)]).size)},0));request.onerror=()=>reject(request.error)});
    db.close();
   }catch{}
   const mediaKeys=['memento.profilePic','memento.profileBanner','memento.profileNoteMedia','memento.profileFrame'];
   mediaBytes+=mediaKeys.reduce((sum,key)=>sum+localSize(key),0);
   const importedBytes=importedEntriesBytes+['memento.followData','memento.importHistory','memento.chatImportHistory','memento.importedFileName'].reduce((sum,key)=>sum+localSize(key),0);
   const aiBytes=localSize('memento-memo-chat'),wikiBytes=localSize('memento.wikiArticles');
   const excluded=new Set(['memento.entries','memento-memo-chat','memento.wikiArticles','memento.followData','memento.importHistory','memento.chatImportHistory','memento.importedFileName',...mediaKeys]);
   const otherBytes=Array.from({length:localStorage.length},(_,index)=>localStorage.key(index)).filter((key):key is string=>!!key&&!excluded.has(key)).reduce((sum,key)=>sum+localSize(key),0);
   let originUsage:number|null=null,quota:number|null=null;
   try{const estimate=await navigator.storage?.estimate();if(estimate){originUsage=typeof estimate.usage==='number'?estimate.usage:null;quota=typeof estimate.quota==='number'?estimate.quota:null}}catch{}
   const categories={entries:entriesBytes,importedEntries:importedBytes,dms:dmsBytes,media:mediaBytes,aiChats:aiBytes,wiki:wikiBytes,other:otherBytes};
   setStorageUsage({...categories,total:Object.values(categories).reduce((sum,value)=>sum+value,0),originUsage,quota,checkedAt:Date.now()});
  }finally{setStorageLoading(false)}
 };
